/** Original layered WAV effects, generated by tools/audio/build_sfx.py. */
const NAMES = [
  'boss-death-charge',
  'boss-death-break',
  'boss-death-tail',
  'crystal-ram',
  'crystal-ram-hit',
  'cinder-spark',
  'cinder-spark-hit',
  'tide-ribbon',
  'tide-ribbon-hit',
  'astral-cascade',
  'astral-cascade-hit',
  'click',
  'select',
  'skill',
  'drag',
  'queue',
  'cancel',
  'error',
  'gate',
  'round',
  'exchange',
  'cast',
  'combine',
  'heal',
  'shield',
  'victory',
  'defeat',
  'sword',
  'sword-hit',
  'staff',
  'staff-hit',
  'bow',
  'bow-hit',
  'slime-bounce',
  'slime-bounce-hit',
  'mushroom-bonk',
  'mushroom-bonk-hit',
  'pebble-shards',
  'pebble-shards-hit',
  'claw-pounce',
  'claw-pounce-hit',
  'stone-slam',
  'stone-slam-hit',
  'ember-bolt',
  'ember-bolt-hit',
  'gate-crush',
  'gate-crush-hit',
  'spore-volley',
  'spore-volley-hit',
];

const UI = new Set(['click', 'select', 'skill', 'drag', 'queue', 'cancel', 'error']);

function gainFor(name) {
  if (name === 'click') return 0.38;
  if (name === 'drag') return 0.25;
  if (UI.has(name)) return 0.46;
  if (name === 'boss-death-charge') return 0.55;
  if (name === 'boss-death-break') return 0.78;
  if (name === 'boss-death-tail') return 0.58;
  if (name === 'combine') return 0.64;
  if (name.endsWith('-hit')) return 0.78;
  if (name === 'victory' || name === 'defeat') return 0.55;
  if (name === 'gate' || name === 'round') return 0.56;
  return 0.68;
}

function jitterFor(name) {
  if (UI.has(name)) return 0.015;
  if (name === 'combine') return 0.01;
  if (name.startsWith('boss-death')) return 0.01;
  if (name.endsWith('-hit')) return 0.04;
  return 0.035;
}

export const SFX = Object.freeze(
  Object.fromEntries(
    NAMES.map((name) => [
      name,
      Object.freeze({
        file: `./assets/audio/sfx/${name}.wav`,
        gain: gainFor(name),
        jitter: jitterFor(name),
      }),
    ]),
  ),
);

export const SFX_NAMES = Object.freeze([...NAMES]);
